// Integrity test for the hand-maintained AcroForm fixture register.
//
// `apps/feldexa_app/assets/fixtures/catalog.json` is generated byte-checked by
// `tools/corpus/synthetic/generate.dart` and covered by
// `test/synthetic_fixtures_test.dart`, so the issue-#344 AcroForm reference
// fixture is registered in its own file
// (`catalog-acroform.json`) instead of in that generated catalogue. This test
// keeps the separate register honest: a changed PDF without a changed entry, a
// missing file, or a missing generator turns red here instead of drifting
// silently.
//
// Static/host check only: no emulator, no runtime evidence claim.

@TestOn('vm')
library;

import 'dart:convert';
import 'dart:io';
import 'dart:typed_data';

import 'package:flutter_test/flutter_test.dart';

import 'support/package_root.dart';
import 'support/sha256_reference.dart';

const String _registerPath =
    'apps/feldexa_app/assets/fixtures/catalog-acroform.json';
const String _generatedCatalogPath =
    'apps/feldexa_app/assets/fixtures/catalog.json';
const String _fixtureId = 'sf-acroform-001';

Map<String, dynamic> _map(Object? value) {
  return (value as Map<Object?, Object?>).cast<String, dynamic>();
}

List<dynamic> _list(Object? value) {
  return value as List<dynamic>;
}

Uint8List _readBytes(String repositoryRelativePath) {
  return File('${repositoryRoot.path}/$repositoryRelativePath')
      .readAsBytesSync();
}

Map<String, dynamic> _readJson(String repositoryRelativePath) {
  return _map(
    jsonDecode(
      File('${repositoryRoot.path}/$repositoryRelativePath').readAsStringSync(),
    ),
  );
}

bool _exists(String repositoryRelativePath) {
  return File('${repositoryRoot.path}/$repositoryRelativePath').existsSync();
}

void main() {
  late Map<String, dynamic> register;
  late List<Map<String, dynamic>> fixtures;

  setUpAll(() {
    register = _readJson(_registerPath);
    fixtures = _list(register['fixtures']).map(_map).toList(growable: false);
  });

  test('the request is synthetic, deterministic, and has no personal data', () {
    expect(register['schemaVersion'], 1);
    final Map<String, dynamic> rights = _map(register['rights']);
    expect(rights['kind'], 'synthetic');
    expect(rights['thirdPartyContent'], isFalse);
    expect(rights['containsPersonalData'], isFalse);
    expect(rights['rightsCleared'], isTrue);

    final Map<String, dynamic> generator = _map(register['generator']);
    expect(generator['deterministic'], isTrue);
    expect(generator['seed'], 0);
    expect(register['fixtureCount'], fixtures.length);
  });

  test('the register holds exactly the AcroForm reference fixture', () {
    expect(
      fixtures.map((Map<String, dynamic> fixture) => fixture['id']).toList(),
      <String>[_fixtureId],
    );
  });

  test('the fixture is deliberately not part of the generated catalogue', () {
    // Documents the scope decision: `catalog.json` is generated byte-checked by
    // `tools/corpus/synthetic/generate.dart`, and `synthetic_fixtures_test.dart`
    // pins its per-entry schema, so a python-generated fixture must not be
    // added there.
    final Map<String, dynamic> generated = _readJson(_generatedCatalogPath);
    final List<String> generatedIds = _list(generated['fixtures'])
        .map(_map)
        .map((Map<String, dynamic> fixture) => fixture['id'] as String)
        .toList(growable: false);
    expect(generatedIds, isNot(contains(_fixtureId)));
  });

  test('every entry pins its committed bytes, paths, and generator', () {
    for (final Map<String, dynamic> fixture in fixtures) {
      final String id = fixture['id'] as String;
      final String assetPath = fixture['assetPath'] as String;
      final String corpusPath = fixture['corpusPath'] as String;
      final String webPath = fixture['webPath'] as String;
      expect(fixture['kind'], 'synthetic');
      expect(fixture['status'], 'valid');
      expect(fixture['mediaType'], 'application/pdf');

      for (final String path in <String>[assetPath, corpusPath, webPath]) {
        expect(_exists(path), isTrue, reason: '$id: missing $path');
      }
      final Uint8List asset = _readBytes(assetPath);
      expect(asset.length, fixture['sizeBytes'], reason: '$id: size drift');
      expect(
        referenceSha256(asset),
        fixture['sha256'],
        reason: '$id: the committed bytes drifted from the pinned sha256',
      );
      expect(
        _readBytes(corpusPath),
        asset,
        reason: '$id: the corpus copy differs from the canonical asset',
      );
      expect(
        _readBytes(webPath),
        asset,
        reason: '$id: the Web mirror differs from the canonical asset',
      );

      final Map<String, dynamic> generator = _map(fixture['synthetic']);
      final String generatorPath = generator['generator'] as String;
      expect(
        generatorPath,
        _map(register['generator'])['path'],
        reason: '$id: the entry and the register name different generators',
      );
      expect(
        _exists(generatorPath),
        isTrue,
        reason: '$id: the generator $generatorPath does not exist',
      );
    }
  });

  test(
    'the fixture really carries the AcroForm the flattening proof needs',
    () {
      // Without these markers the third export leg would only repeat the two
      // existing legs, so the register test proves the form structurally (byte
      // level) and by page count.
      for (final Map<String, dynamic> fixture in fixtures) {
        final String text = latin1.decode(
          _readBytes(fixture['assetPath'] as String),
        );
        expect(text, startsWith('%PDF-1.7'));
        expect(text.trimRight(), endsWith('%%EOF'));
        expect(text, contains('%FELDEXA-SYNTHETIC-FIXTURE'));
        expect(text, contains('/AcroForm'));
        expect(text, contains('/Subtype /Widget'));
        expect(text, contains('/FT /Tx'));
        expect(
          RegExp(r'/Type\s*/Page\b').allMatches(text).length,
          fixture['pageCount'],
        );
        expect(_list(fixture['pages']).length, fixture['pageCount']);
        for (final dynamic pageValue in _list(fixture['pages'])) {
          final Map<String, dynamic> page = _map(pageValue);
          expect(
            text,
            contains('/MediaBox [0 0 ${page['widthPt']} ${page['heightPt']}]'),
          );
        }
        final Map<String, dynamic> groundTruth = _map(fixture['groundTruth']);
        expect(_list(groundTruth['fields']), isNotEmpty);
      }
    },
  );
}
